import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const t="/ascendc.github.io/pr/5487/assets/vecin_vecout_tscm_move.D_8FvuCM.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopyPad（UBToL1非对齐数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_UBToL1"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_UBToL1.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_UBToL1.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_UBToL1.md"};function o(i,s,d,e,r,u){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>DataCopyPad（UBToL1非对齐数据搬运）</h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为软件仿真实现，是在Matmul高阶API的基础上，利用Matmul高阶API中的workspace GM空间作为数据中转空间，数据先搬入GM，再搬入L1 Buffer。因此，在使用本接口时，需要先使用REGISTER_MATMUL注册高阶API。</p></div><p>该接口提供从Unified Buffer（UB）到L1 Buffer的数据非对齐搬运功能。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>通路：Local Memory-&gt;Local Memory，实际搬运过程是UB-&gt;GM-&gt;L1 Buffer（TSCM）。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopyPad</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyExtParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nd2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">nd2nzParams</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><p><span id="table4835205712588"></span></p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数以及paddingValue（待填充数据值）的数据类型。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><p><span id="zh-cn_topic_0235751031_table33761356"></span></p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>LocalTensor的起始地址需要保证32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。<br>LocalTensor的起始地址需要保证32字节对齐。</td></tr><tr><td>dataCopyParams</td><td>输入</td><td>搬运参数。<br>  • DataCopyExtParams类型，具体参数说明请参考<a href="#table10572141063919">表4</a>。</td></tr><tr><td>nd2nzParams</td><td>输入</td><td>从UB-&gt;L1 Buffer（VECIN/VECOUT-&gt;TSCM）进行数据搬运时，可以进行ND到NZ的数据格式转换。nd2nzParams是用于控制数据格式转换的参数，Nd2NzParams类型，具体参数请参考<a href="DataCopy_UBToL1_ND2NZ.html">DataCopy（UBToL1随路转换-ND2NZ搬运）</a>中的介绍。<br><strong>注意：本接口Nd2NzParams的ndNum仅支持设置为1</strong>。</td></tr></tbody></table><p><strong>表3</strong> DataCopyExtParams结构体参数定义</p><p><span id="table10572141063919"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>blockCount</td><td>指定该指令包含的连续传输数据块个数，数据类型为uint16_t，取值范围：blockCount∈[1, 4095]。</td></tr><tr><td>blockLen</td><td>指定该指令每个连续传输数据块长度，<strong>该指令支持非对齐搬运</strong>，<strong>每个连续传输数据块长度单位为字节</strong>。数据类型为uint32_t，取值范围：blockLen∈[1, 2097151]<strong>，blockLen必须是sizeof(T)的整数倍，需要注意UB不要超限</strong>。</td></tr><tr><td>srcStride</td><td>源操作数，相邻连续数据块的间隔（前面一个数据块的尾与后面数据块的头的间隔）。单位为dataBlock(32字节)。<br>数据类型为uint32_t，srcStride不要超出该数据类型的取值范围。</td></tr><tr><td>dstStride</td><td>目的操作数，相邻连续数据块间的间隔（前面一个数据块的尾与后面数据块的头的间隔）。单位为dataBlock(32字节)。数据类型为uint32_t，dstStride不要超出该数据类型的取值范围。</td></tr><tr><td>rsv</td><td>保留字段。</td></tr></tbody></table><p>下面给出如下场景的配置示例：</p><ul><li><p><strong>UB-&gt;L1 Buffer（VECIN/VECOUT-&gt;TSCM）</strong></p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><p>内部实现涉及AIC和AIV之间的通信，实际搬运路径为UB（VECIN/VECOUT）-&gt;GM-&gt;L1 Buffer（TSCM），<strong>发送通信消息会有开销，性能会受到影响</strong>。</p></div><p>如<a href="#fig9329040132719">图1 UB-&gt;L1 Buffer（VECIN/VECOUT-&gt;TSCM）搬运示意图</a>所示，展示了从UB搬运到GM，再搬运到L1 Buffer的过程：示例中数据类型为half，单个datablock（32字节）含有16个half元素，源操作数中的A1~A6、B1~B6、C1~C6为需要进行搬运的数据。</p><ul><li><p>从UB-&gt;GM的搬运，数据存储格式没有发生转变，依然是ND。</p><ul><li><strong>blockCount</strong>为需要搬运的连续传输数据块个数，设置为3；</li><li><strong>blockLen</strong>为一个连续传输数据块的大小（单位为字节），设置为6 * 32 = 192；</li><li><strong>srcStride</strong>为源操作数相邻连续数据块的间隔（前面一个数据块的尾与后面数据块的头的间隔），源操作数物理位置为UB，其单位为datablock，两个连续传输数据块（A1~A6、B1~B6）中间相隔1个A7，因此srcStride设置为1；</li><li><strong>dstStride</strong>为目的操作数，相邻连续数据块间的间隔（前面一个数据块的尾与后面数据块的头的间隔），目的操作数逻辑位置为GM，其单位为字节，两个连续传输数据块（A1~A6、B1~B6）中间相隔2个空白的datablock，因此dstStride设置为64字节。</li></ul></li><li><p>从GM-&gt;L1 Buffer的搬运，数据存储格式由ND转换为NZ。</p><ul><li><strong>ndNum</strong>固定为1，即A1~A6、B1~B6、C1~C6视作一整个ndMatrix；</li><li><strong>nValue</strong>为ndMatrix的行数，即为3行；</li><li><strong>dValue</strong>为ndMatrix中一行包含的元素个数，即为6 * 16 = 96个元素；</li><li><strong>srcNdMatrixStride</strong>为相邻ndMatrix之间的距离，因为仅涉及1个ndMatrix，所以可填为0；</li><li><strong>srcDValue</strong>表明ndMatrix的第x行和第x+1行所相隔的元素个数，如A1~B1的距离，即为8个datablock，8 * 16 = 128个元素；</li><li><strong>dstNzC0Stride</strong>为src同一行的相邻datablock在NZ矩阵中相隔datablock数，如A1~A2的距离，即为7个datablock （A1 + 空白 + B1 + 空白 + C1 + 空白 * 2）；</li><li><strong>dstNzNStride</strong>为src中ndMatrix的相邻行在NZ矩阵中相隔多少个datablock，如A1~B1的距离，即为2个datablock（A1 + 空白）；</li><li><strong>dstNzMatrixStride</strong>为相邻NZ矩阵之间的元素个数，因为仅涉及1个NZ矩阵，所以可以填为0。</li></ul></li></ul><p><strong>图1</strong> UB-&gt;L1 Buffer（VECIN/VECOUT-&gt;TSCM）搬运示意图<span id="fig9329040132719"></span></p><p><img src="`+t+`" alt title="VECIN-VECOUT--TSCM搬运示意图"></p></li></ul><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>特别地，针对Ascend 950PR/Ascend 950DT，设置srcStride和dstStride参数时，数据类型为int64_t，取值范围为[0, 65535]。</li></ul></div><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例展示<a href="#fig9329040132719">图1</a>所示的场景：数据类型为half，单个DataBlock（32字节）含16个half元素，将UB中的ND格式数据经GM中转后，以NZ格式搬入L1 Buffer。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="mi">3</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">7</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="mi">7</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">6</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tscmAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="c1">// 源操作数：UB。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECIN</span><span class="p">,</span><span class="w"> </span><span class="n">ubAddr</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：L1 Buffer。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">TSCM</span><span class="p">,</span><span class="w"> </span><span class="n">tscmAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">;</span>
<span class="c1">// UB（VECIN）-&gt;GM阶段搬运3个连续传输数据块。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 每个连续传输数据块包含6个DataBlock。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="c1">// 源操作数在UB，单位为DataBlock；相邻行之间跳过1个DataBlock。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// 中转目的端为GM，单位为字节；相邻行之间保留2个空白DataBlock，即64B。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="c1">// 保留字段，固定填0。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">rsv</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">nd2nzParams</span><span class="p">;</span>
<span class="c1">// 本接口约束ndNum仅支持设置为1。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">ndNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// ND矩阵高度为3行。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">nValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 每行宽度为6个DataBlock。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">dValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>
<span class="c1">// 仅1个ND矩阵，不涉及相邻ND矩阵间隔。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">srcNdMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// GM中相邻行起始地址间隔为8个DataBlock。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">srcDValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>
<span class="c1">// 目的NZ中同一源行的相邻DataBlock间隔为7个DataBlock。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">dstNzC0Stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">7</span><span class="p">;</span>
<span class="c1">// 目的NZ中相邻源行转换后的起始地址间隔为2个DataBlock。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">dstNzNStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 仅1个NZ矩阵。</span>
<span class="n">nd2nzParams</span><span class="p">.</span><span class="n">dstNzMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">nd2nzParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const _=a(c,[["render",o]]);export{m as __pageData,_ as default};
